from collections import defaultdict

class Warehouse:
    def __init__(self):
        self.inventory = defaultdict(int)
        self.orders = []

    def receive_shipment(self, product, quantity):
        self.inventory[product] += quantity

    def place_order(self, product, quantity):
        self.orders.append((product, quantity))

    def fulfill_orders(self):
        for product, quantity in self.orders:
            if self.inventory[product] >= quantity:
                self.inventory[product] -= quantity
            else:
                print(f"Insufficient stock for {product}. Only {self.inventory[product]} available.")
        self.orders = []  # Reset orders list after fulfilling

    def display_inventory(self):
        return dict(self.inventory)

def predict_next_state(warehouse, actions):
    for action in actions:
        if action['type'] == 'receive_shipment':
            warehouse.receive_shipment(action['product'], action['quantity'])
        elif action['type'] == 'place_order':
            warehouse.place_order(action['product'], action['quantity'])
        elif action['type'] == 'fulfill_orders':
            warehouse.fulfill_orders()

    return warehouse.display_inventory()

# Example usage
if __name__ == "__main__":
    warehouse = Warehouse()
    actions = [
        {'type': 'receive_shipment', 'product': 'shoes', 'quantity': 100},
        {'type': 'receive_shipment', 'product': 't-shirts', 'quantity': 50},
        {'type': 'place_order', 'product': 'shoes', 'quantity': 30},
        {'type': 'place_order', 'product': 't-shirts', 'quantity': 20},
        {'type': 'fulfill_orders'}
    ]

    next_state = predict_next_state(warehouse, actions)
    print("Next State of the Warehouse Inventory:", next_state)
