        next_state = self.state_transitions[current_state].get(command, None)

        if next_state is not None:
            print(f"Executing command '{command}' on {device_name}. New state: {next_state}")
            self.devices[device_name] = next_state
        else:
            print(f"Invalid command '{command}' for device {device_name}.")

